# IMPERIA COLD WAR — Approved France v5 recipient-owned bilateral agreements.
"""Generate only v5 offer runtime files; preserve accepted legacy compacts."""
from pathlib import Path
from decimal import Decimal
import json, importlib.util, re
HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[1]
spec=importlib.util.spec_from_file_location('france_v5_script_ast',HERE.parent/'vietnam_1970/script_ast.py')
AST=importlib.util.module_from_spec(spec);spec.loader.exec_module(AST)
SOURCE=HERE/'approved_design_v5.json'

def num(v):
 s=format(Decimal(str(v)), 'f').rstrip('0').rstrip('.') if '.' in str(v) else str(v)
 return s if s and s!='-0' else '0'
def block(key,*rows):return key+' = {\n'+'\n'.join(str(r) for r in rows if r is not None)+'\n}'
def negate(s):return block('NOT',s)
def either(*rows):return block('OR',*rows)
def check(var,value=0):return block('check_variable',f'{var} = {value}')
def setvar(var,value):return block('set_variable',f'{var} = {value}')
def conditional(guard,*rows):return block('if',block('limit',guard),*rows)
PREFIX='COLDWAR_FRA_v5_'
CATEGORY='COLDWAR_FRA_v5_agreements'
HEADER='# IMPERIA COLD WAR — France v5 recipient-owned bilateral agreements.\n# Generated by tools/france_1970/build_offers_v5.py from approved_design_v5.json.\n'
LEGACY={
'gaullist_franco_german_consultations':'military_industry','gaullist_east_west_consultations':'science_energy',
'orthodox_european_independence_offer':'military_industry','orthodox_soviet_dialogue_offer':'training',
'liberal_common_market_offer':'commerce','liberal_atlantic_science_offer':'science_energy',
'centre_benelux_consultation_offer':'civil_resilience','centre_italian_civic_offer':'civil_industry',
'francophone_engineering_exchange':'civil_industry','reciprocal_professional_courses':'training',
'joint_water_research':'science_energy','cross_border_rescue_protocol':'civil_resilience',
'reciprocal_small_trade':'commerce','mutual_rural_credit':'civil_industry',
'bilateral_proprietor_contracts':'commerce','reciprocal_officer_exchange':'training'}

def compile_offers():
 D=json.loads(SOURCE.read_text(encoding='utf-8-sig'));offers=D['offers'];nodes={n['id']:n for n in D['nodes']};families=D['agreement_rules']['families']
 assert len(offers)==50 and len(families)==6
 old=json.loads((HERE/'approved_design.json').read_text(encoding='utf-8-sig'))
 assert set(LEGACY)=={o['focus'] for o in old['offers'] if o['duration_days']}
 loc={CATEGORY:'French Bilateral Agreements',CATEGORY+'_desc':'Proposals and standing agreements with France.',PREFIX+'no_mutual_sanctions_tt':'No diplomatic, financial, economic or military sanctions between the signatories.',PREFIX+'reissue_cooldown_tt':'At least 180 days since the previous proposal.'}
 effects=[];triggers=[];ideas=[];decisions=[]
 # All pair checks run in the explicitly fixed recipient's country scope.
 relations=['exists = yes','is_subject = no','NOT = { has_war_with = FRA }','FRA = { exists = yes is_subject = no IMP_is_1970_scenario = yes }']
 relations.append(negate(either(*[block('is_in_array',f'array = imp_{kind}_sanc_{direction}', 'value = FRA') for kind in ('dip','fin','eco','mil') for direction in ('on_us','by_us')])))
 triggers.append(block(PREFIX+'relations_valid',*relations))
 for fam in families:
  legacy=[o for o in old['offers'] if LEGACY.get(o['focus'])==fam]
  # Reserve both already accepted and still quoted legacy contracts. New legacy senders are hidden.
  clauses=[]
  for o in legacy:
   clauses.append(negate(f'has_idea = {o["id"]}_treaty'))
   clauses.append(negate(block('AND','has_event_target = COLDWAR_FRA_compact_partner',block('event_target:COLDWAR_FRA_compact_partner',f'has_country_flag = {o["id"]}_active'))))
   clauses.append(negate(block('AND','has_event_target = COLDWAR_FRA_offer_recipient',block('event_target:COLDWAR_FRA_offer_recipient',f'has_country_flag = {o["id"]}_pending'))))
  triggers.append(block(PREFIX+fam+'_legacy_free',*clauses))
  triggers.append(block(PREFIX+fam+'_unreserved',check(PREFIX+fam+'_active'),check(PREFIX+fam+'_pending'),PREFIX+fam+'_legacy_free = yes'))
 active_dispatch={f:[] for f in families};pending_dispatch={f:[] for f in families}

 for index,o in enumerate(offers,1):
  O=o['id'];P=o['partner'];fam=o['family'];n=nodes[O]
  assert O.startswith('COLDWAR_FRA_v5_') and not o['france']['awards'] and not o['partner_terms']['awards']
  a=PREFIX+fam+'_active';q=PREFIX+fam+'_pending';flag=O+'_pending';active=O+'_active';sent=O+'_sent'
  fp=O+'_france_party';fe=O+'_france_epoch';rp=O+'_recipient_party';repoch=O+'_recipient_epoch'
  side_ideas={}
  for side,terms in [('france',o['france']),('partner',o['partner_terms'])]:
   branches=['bba','legacy'] if any('all' not in D['equipment_families'][k]['targets'] for k in terms['equipment']) else ['all']
   side_ideas[side]=[(branch,O+'_'+side+'_spirit'+('' if branch=='all' else '_'+branch)) for branch in branches]
   for branch,idea in side_ideas[side]:
    equipment={}
    for family,delta in terms['equipment'].items():
     targets=D['equipment_families'][family]['targets'];classes=targets.get('all',targets.get('By Blood Alone' if branch=='bba' else 'without By Blood Alone'))
     assert classes,(O,side,family,branch)
     for cls in classes:equipment[cls]=equipment.get(cls,Decimal(0))+Decimal(str(delta))
    # Both flags and family identifiers must exist before either half is granted.
    if side=='france':linked=['tag = FRA',check(a,index),f'has_country_flag = {active}',block(P,'exists = yes',check(a,index),f'has_country_flag = {active}')]
    else:linked=[f'tag = {P}',check(a,index),f'has_country_flag = {active}',block('FRA','exists = yes',check(a,index),f'has_country_flag = {active}')]
    ideas.append(block(idea,'picture = generic_diplomatic_treaty','allowed = { always = no }','removal_cost = -1',block('cancel',negate(block('AND',*linked))),block('modifier',*[f'{k} = {num(v)}' for k,v in terms['mods'].items()]),block('equipment_bonus',*[block(cls,f'build_cost_ic = {num(delta)}','instant = yes') for cls,delta in equipment.items()]) if equipment else ''))
    loc[idea]=o['title'];loc[idea+'_desc']='A standing bilateral programme, maintained by both signatories. It survives changes of government and ends on withdrawal, mutual war or bilateral sanctions.'
  def grant(side):
   variants=side_ideas[side]
   if variants[0][0]=='all':return f'add_ideas = {variants[0][1]}'
   return conditional('has_dlc = "By Blood Alone"',f'add_ideas = {variants[0][1]}')+'\n'+block('else',f'add_ideas = {variants[1][1]}')
  def has_own_idea(side):return either(*[f'has_idea = {idea}' for _,idea in side_ideas[side]])
  def remove_own(side):return '\n'.join(f'remove_ideas = {idea}' for _,idea in side_ideas[side])
  def cost(side):
   t=o['france'] if side=='france' else o['partner_terms']
   return '\n'.join([block('set_temp_variable','treasury_change = '+num(Decimal(str(t['treasury_millions']))/1000)),'modify_treasury_effect = yes','add_political_power = '+num(t['political_power'])])
  def afford(side):
   t=o['france'] if side=='france' else o['partner_terms']
   return '\n'.join([block('check_variable','var = treasury','value = '+num(-Decimal(str(t['treasury_millions']))/1000),'compare = greater_than_or_equals'),negate('has_political_power < '+num(-t['political_power']))])
  parent_receipts=[either(*[f'has_country_flag = COLDWAR_FRA_{key}_earned' for key in group]) for group in n['parents']]
  mandate='\n'.join(['tag = FRA','exists = yes','IMP_is_1970_scenario = yes','is_subject = no',f'COLDWAR_FRA_{o["group"]}_government = yes']+parent_receipts)
  cooldown=either(negate(f'has_country_flag = {sent}'),block('has_country_flag',f'flag = {sent}','days > 179'))
  can_send='\n'.join([mandate,PREFIX+fam+'_unreserved = yes',block(P,PREFIX+'relations_valid = yes'),cooldown])
  triggers.append(block(O+'_can_send',can_send))
  family_tt=PREFIX+fam+'_available_tt'
  loc[family_tt]='No active or pending '+fam.replace('_',' ')+' agreement with France.'
  no_sanc=negate(either(*[block('is_in_array',f'array = imp_{kind}_sanc_{direction}','value = FRA') for kind in ('dip','fin','eco','mil') for direction in ('on_us','by_us')]))
  public=block(P,'exists = yes','is_subject = no','NOT = { has_war_with = FRA }',block('custom_trigger_tooltip','tooltip = '+PREFIX+'no_mutual_sanctions_tt',no_sanc))+'\n'+block('custom_trigger_tooltip','tooltip = '+family_tt,PREFIX+fam+'_unreserved = yes')+'\n'+block('custom_trigger_tooltip','tooltip = '+PREFIX+'reissue_cooldown_tt',cooldown)
  triggers.append(block(O+'_visible_send_requirements',public))
  # A pending offer is read in the recipient's ROOT. All quote values are per pair.
  seen='\n'.join([f'tag = {P}',f'has_country_flag = {flag}',negate(block('has_country_flag',f'flag = {flag}','days > 89')),check(q,index),block('FRA',check(q,index),f'has_country_flag = {flag}')])
  triggers.append(block(O+'_pending_visible',seen))
  valid='\n'.join([seen,PREFIX+'relations_valid = yes',block('FRA',mandate,either(f'has_completed_focus = {O}',f'has_country_flag = {O}_earned'),check('ruling_party',fp),check('COLDWAR_FRA_government_epoch',fe),check(a),PREFIX+fam+'_legacy_free = yes')])
  triggers.append(block(O+'_pending_valid',valid))
  triggers.append(block(O+'_can_accept',valid,afford('partner'),block('FRA',f'has_completed_focus = {O}',afford('france'))))
  def visible_afford(side):
   terms=o['france'] if side=='france' else o['partner_terms'];amount=num(-Decimal(str(terms['treasury_millions']))/1000)
   tt=PREFIX+'treasury_'+amount.replace('.','_')+'_tt'
   loc[tt]='[THIS.GetNameWithFlag] §YTreasury§!: at least §Y$'+amount+' Billion§!'
   return block('custom_trigger_tooltip','tooltip = '+tt,block('check_variable','var = treasury','value = '+amount,'compare = greater_than_or_equals'))+'\n'+negate('has_political_power < '+num(-terms['political_power']))
  accept_fam_tt=PREFIX+fam+'_accept_free_tt'
  loc[accept_fam_tt]='No active '+fam.replace('_',' ')+' agreement with France.'
  public_accept='\n'.join(['exists = yes','is_subject = no','NOT = { has_war_with = FRA }',block('custom_trigger_tooltip','tooltip = '+PREFIX+'no_mutual_sanctions_tt',no_sanc),visible_afford('partner'),block('FRA','exists = yes','is_subject = no',block('custom_trigger_tooltip','tooltip = '+accept_fam_tt,check(a),PREFIX+fam+'_legacy_free = yes'),visible_afford('france'))])
  triggers.append(block(O+'_visible_accept_requirements',public_accept))
  linked='\n'.join([block('FRA',check(a,index),f'has_country_flag = {active}'),block(P,check(a,index),f'has_country_flag = {active}')])
  triggers.append(block(O+'_pair_active',linked))
  triggers.append(block(O+'_signatory',either('tag = FRA',f'tag = {P}'),O+'_pair_active = yes'))
  # All lifecycle effects enter fixed tags, so callback ROOT/PREV never identifies a different pair.
  clear_france=conditional(check(q,index),setvar(q,0))+'\n'+f'clr_country_flag = {flag}'
  clear_partner=conditional(check(q,index),setvar(q,0))+'\n'+f'clr_country_flag = {flag}'
  effects.append(block(O+'_clear_pending',block('FRA',clear_france),block(P,clear_partner)))
  sendbody=[setvar(q,index),f'set_country_flag = {flag}',f'set_country_flag = {sent}',setvar(fp,'ruling_party'),setvar(fe,'COLDWAR_FRA_government_epoch'),block(P,setvar(q,index),f'set_country_flag = {flag}')]
  effects.append(block(O+'_send',conditional(O+'_can_send = yes',*sendbody)))
  # Preview operations are deliberately outside the real consent/funds/party guards.
  effects.append(block(O+'_focus_preview','custom_effect_tooltip = TT_IF_THEY_ACCEPT',block('effect_tooltip',cost('france'),grant('france'),block(P,cost('partner'),grant('partner')))))
  effects.append(block(O+'_recipient_preview',block('effect_tooltip',cost('partner'),grant('partner'),block('FRA',cost('france'),grant('france')))))
  # Flags are established first to keep native idea-cancel checks valid while both grants run.
  acceptbody=[block('FRA',setvar(a,index),f'set_country_flag = {active}'),setvar(a,index),f'set_country_flag = {active}',block('FRA',cost('france'),grant('france')),cost('partner'),grant('partner'),O+'_clear_pending = yes']
  effects.append(block(O+'_accept',conditional(O+'_can_accept = yes',*acceptbody)))
  clear_a=lambda side:conditional(check(a,index),setvar(a,0))+'\n'+f'clr_country_flag = {active}'+'\n'+remove_own(side)
  effects.append(block(O+'_end',block('FRA',clear_a('france')),block(P,clear_a('partner'))))
  effects.append(block(O+'_withdraw',conditional(O+'_signatory = yes',O+'_end = yes')))
  effects.append(block(O+'_withdraw_preview',block('effect_tooltip',block('FRA',*[conditional(f'has_idea = {idea}',f'remove_ideas = {idea}') for _,idea in side_ideas['france']]),block(P,*[conditional(f'has_idea = {idea}',f'remove_ideas = {idea}') for _,idea in side_ideas['partner']]))))
  live=block(P,PREFIX+'relations_valid = yes',check(a,index),f'has_country_flag = {active}',has_own_idea('partner'))+'\n'+has_own_idea('france')
  effects.append(block(O+'_maintain_active',conditional(negate(block('AND',live)),O+'_end = yes')))
  effects.append(block(O+'_maintain_pending',conditional(negate(block(P,O+'_pending_valid = yes')),O+'_clear_pending = yes')))
  active_dispatch[fam].append(conditional(check(a,index),O+'_maintain_active = yes'))
  pending_dispatch[fam].append(conditional(check(q,index),O+'_maintain_pending = yes'))
  # Ordinary recipient-owned decisions. The sender has only fixed-counterpart reissue/cancel controls.
  common=['cost = 0','fire_only_once = no','icon = GFX_decision_generic_political_discourse']
  decisions.append(block(O+'_accept_decision',*common,block('allowed',f'original_tag = {P}'),block('visible',O+'_pending_visible = yes'),block('available',O+'_visible_accept_requirements = yes',block('hidden_trigger',O+'_can_accept = yes')),block('complete_effect',O+'_recipient_preview = yes',block('hidden_effect',O+'_accept = yes')),'ai_will_do = { base = 4 }'))
  decisions.append(block(O+'_decline_decision',*common,block('allowed',f'original_tag = {P}'),block('visible',O+'_pending_visible = yes'),block('complete_effect',block('hidden_effect',conditional(O+'_pending_visible = yes',O+'_clear_pending = yes'))),'ai_will_do = { base = 1 }'))
  reissue='\n'.join([f'has_completed_focus = {O}',O+'_can_send = yes'])
  decisions.append(block(O+'_reissue_decision',*common,'allowed = { original_tag = FRA }',block('visible',f'has_completed_focus = {O}',negate(check(a,index)),negate(check(q,index))),block('available',O+'_visible_send_requirements = yes',block('hidden_trigger',reissue)),block('complete_effect',O+'_focus_preview = yes',block('hidden_effect',conditional(reissue,O+'_send = yes'))),'ai_will_do = { base = 0 }'))
  cancel=check(q,index)+'\n'+f'has_country_flag = {flag}'
  decisions.append(block(O+'_cancel_decision',*common,'allowed = { original_tag = FRA }',block('visible',cancel),block('complete_effect',block('hidden_effect',conditional(cancel,O+'_clear_pending = yes'))),'ai_will_do = { base = 0 }'))
  decisions.append(block(O+'_withdraw_decision',*common,block('allowed',either('original_tag = FRA',f'original_tag = {P}')),block('visible',O+'_signatory = yes'),block('complete_effect',O+'_withdraw_preview = yes',block('hidden_effect',O+'_withdraw = yes')),'ai_will_do = { base = 0 }'))
  loc.update({O+'_accept_decision':'Accept: '+o['title'],O+'_decline_decision':'Decline: '+o['title'],O+'_reissue_decision':'Reissue: '+o['title'],O+'_cancel_decision':'Cancel proposal: '+o['title'],O+'_withdraw_decision':'Withdraw: '+o['title']})
  for suffix in ('accept_decision','decline_decision','reissue_decision','cancel_decision'):
   loc[O+'_'+suffix+'_desc']='France has proposed '+o['title'].lower()+'. The invitation remains open for 90 days. Acceptance establishes the reciprocal programme; refusal applies no agreement costs.' if suffix in ('accept_decision','decline_decision') else ('Submit the named agreement for a new decision by its counterpart.' if suffix=='reissue_decision' else 'Withdraw the outstanding invitation before an agreement enters into force.')
  loc[O+'_withdraw_decision_desc']='Terminate the standing programme and remove its effects from both signatories.'
 # Six family slots: no world scan, array iteration, event queue or global recipient target.
 maintenance=[]
 for fam in families:
  a=PREFIX+fam+'_active';q=PREFIX+fam+'_pending'
  maintenance.append(conditional(negate(check(a)),*active_dispatch[fam]))
  maintenance.append(conditional(negate(check(q)),*pending_dispatch[fam]))
 effects.append(block(PREFIX+'offer_maintenance',conditional('tag = FRA',*maintenance)))
 data={'common/scripted_effects/COLDWAR_FRA_1970_v5_offers.txt':'\n'.join(effects),'common/scripted_triggers/COLDWAR_FRA_1970_v5_offers.txt':'\n'.join(triggers),'common/ideas/COLDWAR_FRA_1970_v5_offers.txt':block('ideas',block('country',*ideas)),'common/decisions/COLDWAR_FRA_1970_v5_offers.txt':block(CATEGORY,*decisions),'common/decisions/categories/COLDWAR_FRA_1970_v5_offers.txt':block(CATEGORY,'icon = GFX_decision_generic_political_discourse','allowed = { always = yes }',block('visible','IMP_is_1970_scenario = yes',either('tag = FRA',*[f'original_tag = {p}' for p in sorted({o['partner'] for o in offers})])))}
 for path,raw in data.items():
  before=AST.parse(raw);formatted=AST.format_code(raw);assert AST.parse(formatted)==before,path
  rows=[]
  for line in formatted.splitlines():
   m=re.match(r'^(\s*)(COLDWAR_FRA_[\w]+) = \{',line)
   if m:rows.append(m[1]+'# IMPERIA COLD WAR — French bilateral agreement '+m[2]+'.')
   rows.append(line)
  f=ROOT/path;f.parent.mkdir(parents=True,exist_ok=True);f.write_text(HEADER+'\n'.join(rows)+'\n',encoding='utf-8')
 f=ROOT/'localisation/english/COLDWAR_FRA_1970_v5_offers_l_english.yml';f.parent.mkdir(parents=True,exist_ok=True)
 f.write_text(HEADER+'l_english:\n'+''.join(' '+k+':0 "'+v.replace('"',"'")+'"\n' for k,v in loc.items()),encoding='utf-8-sig')
 # Complete transitive localisation audit, including every ordinary decision and idea variant.
 required={CATEGORY}
 for row in decisions:
  required.add(AST.parse(row)[0][0])
 for row in ideas:required.add(AST.parse(row)[0][0])
 for raw in data.values():
  required.update(v for k,op,v in AST.walk(AST.parse(raw)) if k in ('custom_effect_tooltip','name','title','desc') and isinstance(v,str) and v.startswith('COLDWAR_FRA_'))
 assert required<=loc.keys(),sorted(required-loc.keys())
 assert not any(k in ('every_country','every_other_country','for_each_scope_loop','for_each_loop','add_timed_idea','add_tech_bonus','add_equipment_bonus') for raw in data.values() for k,op,v in AST.walk(AST.parse(raw)))
 print('France v5:',len(offers),'fixed-recipient agreement pairs;',len(ideas),'DLC-aware spirit providers;',len(decisions),'ordinary decisions; six bounded families.')
 return D

if __name__=='__main__':compile_offers()
